use std::{collections::{BTreeMap,BTreeSet},fs,io::{BufRead,BufReader,Read},path::Path};
use serde_json::{json,Value}; use sha2::{Digest,Sha256};
const R:&str="/home/ubuntu/src/zopro-perf-work/ready-solver246";
mod owners { use super::*; include!("/home/ubuntu/src/zopro-perf-work/paired-weighted-profile235/metadata.rs"); pub fn get(m:&str,b:&str)->(u32,BTreeSet<u32>){profile_owners(m,b)} }
